DROP TABLE IF EXISTS `CALENDER`;
CREATE TABLE `CALENDER` (
  `id_course` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `code` varchar(255) DEFAULT NULL,
  `mediaserver_link` varchar(1000) DEFAULT NULL,
  `moodle_link` varchar(1000) DEFAULT NULL,
  `quizlet_link` varchar(1000) DEFAULT NULL,
  `discord_link` varchar(1000) DEFAULT NULL,
  `color` varchar(255) NOT NULL,
  `id_user` varchar(255) NOT NULL,
  `id_element` varchar(255) NOT NULL COMMENT 'id de toute cette ligne',
  PRIMARY KEY (`id_element`),
  UNIQUE KEY `id_user` (`id_user`,`id_course`),
  UNIQUE KEY `CALENDER_COURSE_EVENT_null_fk` (`id_course`),
  KEY `CALENDER_USER_null_fk` (`id_user`),
  CONSTRAINT `CALENDER_USER_null_fk` FOREIGN KEY (`id_user`) REFERENCES `USER` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `EVENT_DATE`;
CREATE TABLE `EVENT_DATE` (
