  `event_id` varchar(255) NOT NULL,
  `date` date NOT NULL,
  `user_id` varchar(255) NOT NULL,
  `hour_start` time DEFAULT NULL,
  `hour_end` time DEFAULT NULL,
  `no_room` varchar(255) DEFAULT NULL,
  `building` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`event_id`,`date`,`user_id`),
  KEY `EVENT_DATE_USER_id_fk` (`user_id`),
  CONSTRAINT `EVENT_DATE_SCHEDULE_id_fk` FOREIGN KEY (`event_id`) REFERENCES `SCHEDULE` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

