  `id` varchar(255) NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `day` varchar(255) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `hour_start` time NOT NULL,
  `hour_end` time NOT NULL,
  `type` varchar(255) DEFAULT NULL,
  `occurence_unique` tinyint(1) DEFAULT NULL,
  `periodicity` int DEFAULT NULL,
  `no_room` varchar(255) DEFAULT NULL,
  `building` varchar(255) DEFAULT NULL,
  `id_course` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `SCHEDULE_COURSE_EVENT_null_fk` (`id_course`),
  KEY `SCHEDULE_EVENT_TYPES_type_fk` (`type`),
  CONSTRAINT `SCHEDULE_CALENDER_id_element_fk` FOREIGN KEY (`id_course`) REFERENCES `CALENDER` (`id_element`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `SCHEDULE_EVENT_TYPES_type_fk` FOREIGN KEY (`type`) REFERENCES `EVENT_TYPES` (`type`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Contient les événements liés à un cours dans CALENDAR';

